  0% {
    filter: hue-rotate(0deg);
    box-shadow:
      0 0 12px #ff3b30,
      0 0 24px #ff3b30;
  }
  50% {
    filter: hue-rotate(180deg);
    box-shadow:
      0 0 15px #34c759,
